public class OcGimmick_TreasureBox : OcGimmick_TreasureBoxBase
{
	public enum RarityType
	{
		Common,
		Epic,
		Legendary
	}

	[SerializeField]
	private RarityType _RarityType;

	[SerializeField]
	private bool _ForceSpawn;

	private int _Rarity;

	private bool _EnableEnchantPoint;

	[SerializeReference]
	private IOcTreasureLottery _treasureLottery = new OcTreasureLottery_General();

	public Vector3 DropPos => base.transform.position + Vector3.up * 0.8f;

	public Vector3 DropForward => base.transform.forward;

	public RarityType RarityTypeVal => _RarityType;

	public bool EnableEnchantPoint => _EnableEnchantPoint;

	protected override void Start()
	{
		if (_ForceSpawn)
		{
			_Spawn = true;
		}
		else if (UnityEngine.Random.Range(0f, 1f) <= 1f / 3f)
		{
			_Spawn = true;
		}
		_EnableEnchantPoint = UnityEngine.Random.value <= 1f / 3f;
		base.Start();
	}

	protected override void doComplete()
	{
		base.doComplete();
		_treasureLottery.Lottery(this);
	}
}
