public class OcTreasureLottery_Fix : IOcTreasureLottery
{
	[Serializable]
	public class ItemInfo
	{
		public OcItemID ItemID = new OcItemID();

		public int Num = 1;
	}

	[SerializeField]
	private ItemInfo[] _itemInfos = new ItemInfo[0];

	public void Lottery(OcGimmick_TreasureBox treasureBox)
	{
		int num = 1;
		if (treasureBox.FirstOpen_NetUserId == SingletonMonoBehaviour<OcNetMng>.Inst.NetUserId_Master && UnityEngine.Random.value < OcPlMng.LocalPl.SkillCtrl.TreasureHunter_Prob)
		{
			num++;
			SingletonMonoBehaviour<OcMessageMng>.Inst.LocalPlMessage(DescriptionBuilder.BuildText(LocalizationManager.GetTranslation("100_UI/Speech/TresureHunter/Success", true, 0, true, false, (GameObject)null, (string)null)));
		}
		ItemInfo[] itemInfos = _itemInfos;
		foreach (ItemInfo itemInfo in itemInfos)
		{
			OcItem item = new OcItem(itemInfo.ItemID.ItemData);
			if (SingletonMonoBehaviour<OcNetMng>.Inst.IsClient)
			{
				short num2 = (short)(itemInfo.Num * (num - 1));
				if (num2 > 0)
				{
					SingletonMonoBehaviour<OcNetMng>.Inst.NetRPC?.DropItem_TreasureHunterAdditionalDrop.Send(item, num2, treasureBox.BuffListId, treasureBox.PosHash);
				}
			}
			else
			{
				drop(item, (byte)(itemInfo.Num * num), treasureBox.DropPos, treasureBox.DropForward);
			}
		}
	}

	private static void drop(OcItem item, byte num, in Vector3 dropPos, in Vector3 dropForward)
	{
		OcDropItemActivateInfo ocDropItemActivateInfo = new OcDropItemActivateInfo();
		ocDropItemActivateInfo.poolType = OcDropItemMng.PoolType.KillDrop_Em;
		ocDropItemActivateInfo.pos = dropPos;
		ocDropItemActivateInfo.item = item;
		ocDropItemActivateInfo.stockNum = num;
		ocDropItemActivateInfo.dropForward = dropForward;
		ocDropItemActivateInfo.dropDeg = 120f;
		SingletonMonoBehaviour<OcDropItemMng>.Inst.activate(ocDropItemActivateInfo);
	}
}

