	public override void TryUse(OcItemStack itemStack, out bool success, out bool needsCooldown)
	{
		if (!SingletonMonoBehaviour<OcItemDataMng>.Inst.BlueprintToRecipeDic.ContainsKey(itemStack.ItemData.Id))
		{
			Debug.Log((object)"設計図の解放アイテムが未設定です");
			success = false;
			needsCooldown = false;
			return;
		}
		int num = SingletonMonoBehaviour<OcItemDataMng>.Inst.BlueprintToRecipeDic[itemStack.ItemData.Id];
		if (SingletonMonoBehaviour<OcItemDataMng>.Inst.IsItemUnlocked(num))
		{
			Debug.Log((object)"レシピ開放済み");
			success = false;
			needsCooldown = false;
			return;
		}
		SingletonMonoBehaviour<OcItemDataMng>.Inst.UnlockRecipe(num);
		itemStack.Decrease(1, isCostingItem: true);
		ItemData itemData_OrNull = SingletonMonoBehaviour<OcItemDataMng>.Inst.GetItemData_OrNull(num);
		if ((bool)itemData_OrNull)
		{
			string message = LocalizationManager.GetTranslation("100_UI/Text/LearnedRecipe", true, 0, true, false, (GameObject)null, (string)null).Replace("[A]", itemData_OrNull.DisplayName);
			UISceneSingleton<OcItemUI_EquipmentMng>.InstUISS?.ItemUseNotify(message);
			if (itemData_OrNull.IsSkill())
			{
				SingletonMonoBehaviour<OcUI_HUDUnlockHandler>.Inst.PopupPetSkillUnlock(itemData_OrNull);
			}
			else
			{
				SingletonMonoBehaviour<OcUI_HUDUnlockHandler>.Inst.PopupCraftUnlock(itemData_OrNull);
			}
		}
		success = true;
		needsCooldown = true;

private void LoadRecipeSaveData()
{
	int[] reicpeUnlocked = SingletonMonoBehaviour<OcPlCharacterManager>.Inst.GetReicpeUnlocked();
	_itemUnlocked.Clear();
	int[] array = reicpeUnlocked;
	foreach (int itemId in array)
	{
		UnlockRecipe(itemId);
	}
	int soulOrbRewardItemCount = SingletonMonoBehaviour<OcPlCharacterManager>.Inst.GetSoulOrbRewardItemCount();
	SoSoulOrbRewardData soulOrbRewardData = OcResidentData.SoulOrbRewardData;
	for (int j = 0; j < soulOrbRewardItemCount; j++)
	{
		if (TryGetBluePrintRecipeItem(soulOrbRewardData.GetRewardItemID(j), out var recipeItem))
		{
			UnlockRecipe(recipeItem);
		}
	}
	ItemData[] array2 = blueprintRecipeList;
	foreach (ItemData itemData in array2)
	{
		if (!IsItemUnlocked(itemData.Id))
		{
			int workBenchId = itemData.WorkBenchId;
			if (craftBenchMap.ContainsKey(workBenchId) && craftBenchMap[workBenchId].Contains(itemData))
			{
				craftBenchMap[workBenchId].Remove(itemData);
			}
		}
	}
}

public bool TryGetBluePrintRecipeItem(int blueprintID, out ItemData recipeItem)
{
	if (SingletonMonoBehaviour<OcItemDataMng>.Inst.BlueprintToRecipeDic.TryGetValue(blueprintID, out var value))
	{
		recipeItem = GetItemData_OrNull(value);
		return !recipeItem.IsNullOrEmpty();
	}
	recipeItem = EmptyData;
	return false;
}

public void SetFavourite(int itemId, bool isFavorite)
{
	if (isFavorite)
	{
		if (!_itemFavouriteList.Contains(itemId))
		{
			_itemFavouriteList.Add(itemId);
		}
	}
	else if (_itemFavouriteList.Contains(itemId))
	{
		_itemFavouriteList.Remove(itemId);
	}
}

public void UnlockRecipe(int itemId)
{
	ItemData itemData_OrNull = GetItemData_OrNull(itemId);
	if (!itemData_OrNull.IsNullOrEmpty())
	{
		UnlockRecipe(itemData_OrNull);
	}
}

public void UnlockRecipe(ItemData item)
{
	if (IsItemUnlocked(item.Id))
	{
		return;
	}
	_itemUnlocked.Add(item.Id);
	if (!item.IsSkill())
	{
		int workBenchId = item.WorkBenchId;
		if (craftBenchMap.ContainsKey(workBenchId) && !craftBenchMap[workBenchId].Contains(item))
		{
			craftBenchMap[workBenchId].Add(item);
		}
	}
	if (RecipeToBlueprintDic.TryGetValue(item.Id, out var value) && SingletonMonoBehaviour<StatisticalDataManager>.Inst.GetItemDeliveredCount(value) == 0f)
	{
		SingletonMonoBehaviour<StatisticalDataManager>.Inst.AddItemDelivered(value, 1);
	}
}

