	CurrentItem = itemData;
	itemSlot.Init(itemData);
	((TMP_Text)itemName).text = itemData.DisplayName;
	((TMP_Text)itemDesc).text = itemData.Description;
	ItemData itemData_OrNull = SingletonMonoBehaviour<OcItemDataMng>.Inst.GetItemData_OrNull(SingletonMonoBehaviour<OcItemDataMng>.Inst.RecipeToBlueprintDic[itemData.Id]);
	if (itemData_OrNull.IsNullOrEmpty())
