	IEnumerable<SoEnemyData> emFromDropItemID = SingletonMonoBehaviour<OcEmMng>.Inst.getEmFromDropItemID(itemData_OrNull.Id, havingEnemyNames.Length);
	dropInfoRoot.SetActiveIfRequired(!emFromDropItemID.Empty());
	IEnumerator<SoEnemyData> enumerator = emFromDropItemID.GetEnumerator();
	TMP_Text[] array = havingEnemyNames;
	foreach (TMP_Text val in array)
	{
		bool flag = enumerator.MoveNext();
		((UnityEngine.Component)(object)val).gameObject.SetActiveIfRequired(flag);
		if (flag)
		{
			val.SetText(enumerator.Current.Name);
		}
	}
	tresureOrGacha.SetActiveIfRequired(itemData_OrNull.ProbInTreasureBox > 0f);
	string text = default(string);
	bool isActive = LocalizationManager.TryGetTranslation(ZString.Concat<string, short>("204_ItemWhereToGet/", itemData_OrNull.Id), ref text, true, true, 0, true, false, (GameObject)null, (string)null);
