	}
	else
	{
		Create_RPC(id);
	}
	return true;
}

public void Create_RPC(int id)
{
	//IL_0096: Unknown result type (might be due to invalid IL or missing references)
	//IL_009b: Unknown result type (might be due to invalid IL or missing references)
	if (_stateDic.ContainsKey(id))
	{
		Debug.LogError((object)$"{id}のサブワールドを生成しようとしましたが、_stateDicが設定済みです。生成中が解放されていない可能性あり。");
		return;
	}
	_stateDic.Add(id, SubWorldState.InstantiateWait);
	AssetReferenceGameObject subWorldPrefab = _subWorldSoList.OcSubWorldSos[id].SubWorldPrefab;
	if (((AssetReference)subWorldPrefab).IsValid() && ((AssetReference)subWorldPrefab).IsDone)
	{
		InstantiateSubWorld(id, (GameObject)((AssetReference)subWorldPrefab).Asset);
		return;
	}
	AsyncOperationHandle<GameObject> handle = ((AssetReferenceT<GameObject>)(object)subWorldPrefab).LoadAssetAsync();
	handle.Completed += onLoaded;
	void onLoaded(AsyncOperationHandle<GameObject> result)
	{
		InstantiateSubWorld(id, result.Result);
		handle.Completed -= onLoaded;
	}
}

private void InstantiateSubWorld(int id, GameObject prefab)
{
	if (!prefab)
	{
		Debug.LogError((object)$"{id}のサブワールドを生成しようとしましたが、プレハブが不正でした");
